@app.post("/drafts/<draft_id>/security-continue")
@app.post("/unpublished/<draft_id>/security-continue")
def unpublished_security_continue(draft_id: str):
    """Explicitly resume exactly the draft whose DataDome check was solved."""
    draft = _find_draft(draft_id)
    if not draft:
        flash("Diese Anzeige wurde nicht gefunden.", "error")
        return redirect(url_for("unpublished"))
    return_endpoint = "unpublished" if _draft_is_true_unpublished(draft) else "index"
    challenge_active = bool(
        draft.get("security_challenge_required")
        and str(draft.get("security_challenge_state") or "") in {"waiting", "timed_out"}
    )
    if not challenge_active:
        flash("Für diese Anzeige wartet aktuell keine Sicherheitsprüfung.", "error")
        return redirect(url_for(return_endpoint))

    state = _load_bulk_publish_state()
    queue = [job for job in state.get("queue", []) if isinstance(job, dict)]
    current = state.get("current") if isinstance(state.get("current"), dict) else {}

    # Keep the exact action that originally hit DataDome. This matters when the
    # check happened before the old listing was deleted: the draft is then still
    # published locally, but the queued action is nevertheless a renewal.
    matching_current = current if str(current.get("draft_id") or "") == draft_id else {}
    matching_queued = next((job for job in queue if str(job.get("draft_id") or "") == draft_id), {})
    if matching_current:
        action = str(matching_current.get("action") or "publish")
    elif matching_queued:
        action = str(matching_queued.get("action") or "publish")
    elif draft.get("renewal_upload_pending") or str(draft.get("published_item_id") or "").strip():
        action = "renew"
    else:
        action = "publish"
    if action not in {"publish", "renew", "renew_without_delete"}:
        action = "renew" if (draft.get("renewal_upload_pending") or str(draft.get("published_item_id") or "").strip()) else "publish"

    draft["security_challenge_manual_continue_at"] = _now()
    # The explicit confirmation is the reliable fallback when DataDome keeps
    # its captcha page visible after the green tick. The next publish stage may
    # open exactly one fresh tab; if Vinted still rejects the clearance, a new
    # real challenge is raised and no further automatic tab is spawned.
    draft["security_challenge_force_fresh_publish"] = True
    draft["status"] = "Fortsetzung nach Sicherheitsprüfung angefordert"
    draft["updated_at"] = _now()
    _replace_draft(draft)

    key = (draft_id, action)
    current_key = (str(current.get("draft_id") or ""), str(current.get("action") or "publish"))
    queued_keys = {(str(job.get("draft_id") or ""), str(job.get("action") or "publish")) for job in queue}
    if key != current_key and key not in queued_keys:
        queue.insert(0, {"draft_id": draft_id, "action": action})
        state["queue"] = queue
        _save_bulk_publish_state(state)
    elif not _bulk_publish_worker_alive() and key == current_key and key not in queued_keys:
        # Recover a stale persisted "current" entry after a worker/process exit.
        queue.insert(0, {"draft_id": draft_id, "action": action})
        state["current"] = {}
        state["queue"] = queue
        _save_bulk_publish_state(state)

    _ensure_bulk_publish_worker()
    flash(
        "Fortsetzung angefordert. Nach der abgeschlossenen Sicherheitsprüfung wird für diesen Auftrag genau ein neuer Vinted-Veröffentlichungstab geöffnet. Falls Vinted die Freigabe noch nicht akzeptiert hat, erscheint wieder eine echte Sicherheitsprüfung.",
        "success",
    )
    return redirect(url_for(return_endpoint))


@app.post("/unpublished/bulk")
def unpublished_bulk_action():
    selected = [str(value).strip() for value in request.form.getlist("draft_ids") if str(value).strip()]
    selected = list(dict.fromkeys(selected))
    if not selected:
        flash("Bitte mindestens eine Anzeige markieren.", "error")
        return redirect(url_for("unpublished"))
    valid = {str(draft.get("id") or ""): draft for draft in _load_drafts() if _draft_is_true_unpublished(draft)}
    selected = [draft_id for draft_id in selected if draft_id in valid]
    action = str(request.form.get("bulk_action") or "").strip()
    if action == "delete":
        try:
            _create_backup("vor-sammel-loeschen")
        except Exception:
            app.logger.exception("Automatic backup before bulk delete failed")
        for draft_id in selected:
            draft = valid.get(draft_id)
            if draft:
                _remove_draft_images(draft)
        _save_drafts([draft for draft in _load_drafts() if str(draft.get("id") or "") not in set(selected)], backup_label="auto-sammel-loeschen")
        flash(f"{len(selected)} lokale Anzeige(n) gelöscht.", "success")
    elif action == "publish":
        state = _load_bulk_publish_state()
        queued = list(state.get("queue", []))
        current = state.get("current") if isinstance(state.get("current"), dict) else {}
        existing = {(str(job.get("draft_id") or ""), str(job.get("action") or "publish")) for job in queued if isinstance(job, dict)}
        current_key = (str(current.get("draft_id") or ""), str(current.get("action") or "publish"))
        added = 0
        skipped_unprocessed = 0
        ordered_selected = sorted(
            selected,
            key=lambda draft_id: 0 if valid[draft_id].get("renewal_upload_pending") else 1,
        )
        for draft_id in ordered_selected:
            draft = valid[draft_id]
            recovery = bool(draft.get("renewal_upload_pending"))
            if not recovery and draft.get("manual_review_confirmed") is not True:
                skipped_unprocessed += 1
                continue
            if _security_wait_timed_out(draft):
                # Do not fail a fresh manual retry because an earlier challenge
                # window has expired. If Vinted still requires a check, the new
                # request raises a fresh challenge and sends the normal push.
                _clear_security_challenge(draft)
            draft["status"] = "Veröffentlichung wartet"
            draft["last_error"] = ""
            draft["updated_at"] = _now()
            _replace_draft(draft)
            queue_action = "renew" if recovery else "publish"
            key = (draft_id, queue_action)
            if key in existing or key == current_key:
                continue
            queued.append({"draft_id": draft_id, "action": queue_action})
            existing.add(key)
            added += 1
        state["queue"] = queued
        _save_bulk_publish_state(state)
        if added:
            _ensure_bulk_publish_worker()
            message = f"{added} Anzeige(n) werden nacheinander eingestellt · {BULK_PUBLISH_DELAY_SECONDS} Sek. Abstand."
            if skipped_unprocessed:
                message += f" {skipped_unprocessed} unbearbeitete Anzeige(n) wurden ausgelassen."
            flash(message, "success")
        elif skipped_unprocessed:
            flash("Die Auswahl enthält nur unbearbeitete Anzeigen. Bitte diese zuerst bearbeiten und bestätigen.", "error")
        else:
            flash("Die ausgewählten Anzeigen sind bereits in der Warteschlange.", "success")
    else:
        flash("Unbekannte Sammelaktion.", "error")
    return redirect(url_for("unpublished"))


